    [BurstCompile(CompileSynchronously = true, FloatPrecision = FloatPrecision.High, FloatMode = FloatMode.Default)]
    public struct MpcWarmFrameJobDouble : IJob
    {
        public doubleMPCState s;
        public doubleMxN A, B;      // REAL (not condensed) dynamics, to advance the plant after each solve
        public doubleN x;            // current plant state -- carried across repeated job.Run() calls
        public doubleN u0;
        public doubleN reference;
