            itersOut[0] = info.iterations;
            changesOut[0] = info.activeSetChanges;
            statusOut[0] = (int)info.status;
            objOut[0] = info.objective;

            Blas.dot(in A, in x, ref xNext);
            Blas.dot(in B, in u0, ref Bu);
            xNext.addInPlace(Bu);
            x.CopyFrom(xNext);
        }
